import { ethers } from 'ethers';
import { TOKENS, NATIVE_TOKEN } from './addresses';
import type { TokenSymbol } from './addresses';

function roundedDecimal(raw: bigint, decimals: number, precision: number) {
  if (!Number.isInteger(precision) || precision < 0 || precision > 100) {
    throw new RangeError('precision must be an integer between 0 and 100');
  }
  const negative = raw < 0n;
  const canonical = ethers.formatUnits(negative ? -raw : raw, decimals);
  const [whole, fraction = ''] = canonical.split('.');
  const scale = 10n ** BigInt(precision);
  let rounded =
    BigInt(whole) * scale + BigInt(fraction.slice(0, precision).padEnd(precision, '0') || '0');
  if ((fraction[precision] ?? '0') >= '5') rounded += 1n;
  return {
    sign: negative ? '-' : '',
    whole: (rounded / scale).toString(),
    fraction: precision ? (rounded % scale).toString().padStart(precision, '0') : '',
  };
}

export function formatAmount(raw: bigint, decimals: number, precision = 4): string {
  const value = roundedDecimal(raw, decimals, precision);
  const fraction = value.fraction.replace(/0+$/, '');
  const whole = value.whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${value.sign}${whole}${fraction ? `.${fraction}` : ''}`;
}

export function parseAmount(amount: string, decimals: number): bigint {
  return ethers.parseUnits(amount, decimals);
}

export function formatToken(raw: bigint, symbol: TokenSymbol): string {
  const tok = TOKENS[symbol];
  return `${formatAmount(raw, tok.decimals)} ${tok.symbol}`;
}

export function formatNative(raw: bigint): string {
  return `${formatAmount(raw, 18)} ${NATIVE_TOKEN.symbol}`;
}

/** Format a price from the oracle (18-decimal bigint) as a USD string */
export function formatPrice(rawPrice: bigint): string {
  const value = roundedDecimal(rawPrice, 18, 6);
  return `$${value.sign}${value.whole}.${value.fraction}`;
}

/** Format basis points as a percentage string */
export function formatBps(bps: bigint | number): string {
  return `${(Number(bps) / 100).toFixed(2)}%`;
}

/** Deadline timestamp (seconds from now, or 0 for no deadline) */
export function makeDeadline(seconds = 300): bigint {
  return seconds > 0 ? BigInt(Math.floor(Date.now() / 1000) + seconds) : 0n;
}

/** Shorten an address for display: 0x1234...abcd */
export function shortAddress(address: string): string {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}
